{
    "name": "008_expert_output_weighted_index_add_accumulation",
    "hf_id": "MiniMaxAI/MiniMax-M2",
    "description": "Critical atomic MoE operation that performs weighted expert output accumulation using index_add_ with element-wise routing weight multiplication. Expert outputs are multiplied by routing weights and scattered back to original token positions using atomic additions.",
    "axes": {
        "batch_size": {
            "type": "var"
        },
        "seq_len": {
            "type": "var"
        },
        "hidden_size": {
            "type": "const",
            "value": 3072
        },
        "num_experts_per_tok": {
            "type": "const",
            "value": 8
        },
        "batch_seq_len": {
            "type": "expr",
            "expression": "batch_size * seq_len"
        },
        "num_selected_tokens": {
            "type": "expr",
            "expression": "batch_size * seq_len * num_experts_per_tok"
        }
    },
    "custom_inputs_entrypoint": "get_inputs",
    "inputs": {
        "final_hidden_states": {
            "shape": [
                "batch_seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Accumulation buffer for all tokens"
        },
        "expert_outputs": {
            "shape": [
                "num_selected_tokens",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Weighted outputs from expert computation"
        },
        "token_indices": {
            "shape": [
                "num_selected_tokens"
            ],
            "dtype": "int64",
            "description": "Original token positions for scatter-add"
        }
    },
    "outputs": {
        "output": {
            "shape": [
                "batch_seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Updated hidden states with expert contributions accumulated"
        }
    },
    "reference": "import torch\n\n\ndef get_inputs(\n    axes_and_scalars: dict[str, ...], device: torch.device\n) -> dict[str, torch.Tensor]:\n    \"\"\"Returns the input arguments for the reference forward pass. Required method.\"\"\"\n    batch_size, seq_len, hidden_size = (\n        axes_and_scalars[\"batch_size\"],\n        axes_and_scalars[\"seq_len\"],\n        axes_and_scalars[\"hidden_size\"],\n    )\n    num_experts_per_tok = axes_and_scalars[\"num_experts_per_tok\"]\n\n    batch_seq_len = batch_size * seq_len\n    num_selected_tokens = batch_size * seq_len * num_experts_per_tok\n\n    # Initialize accumulation buffer with random values (not zeros) to detect no-op\n    final_hidden_states = torch.randn(batch_seq_len, hidden_size, dtype=torch.bfloat16, device=device)\n\n    # Expert outputs (weighted outputs from expert computation)\n    expert_outputs = torch.randn(num_selected_tokens, hidden_size, dtype=torch.bfloat16, device=device)\n\n    # Token indices (which token position each expert output belongs to)\n    # These should be in range [0, batch_seq_len)\n    # Simulate scattered indices with potential duplicates (for top_k > 1)\n    token_indices = torch.randint(\n        0, batch_seq_len, (num_selected_tokens,), dtype=torch.long, device=device\n    )\n\n    return {\n        \"final_hidden_states\": final_hidden_states,\n        \"expert_outputs\": expert_outputs,\n        \"token_indices\": token_indices,\n    }\n\n\n@torch.no_grad()\ndef run(\n    final_hidden_states: torch.Tensor,\n    expert_outputs: torch.Tensor,\n    token_indices: torch.Tensor,\n):\n    \"\"\"\n    Performs atomic accumulation of expert outputs back to token positions.\n    \n    Args:\n        final_hidden_states: Accumulation buffer for all tokens (batch_seq_len, hidden_size)\n        expert_outputs: Weighted outputs from expert computation (num_selected_tokens, hidden_size)\n        token_indices: Original token positions (num_selected_tokens,)\n        \n    Returns:\n        Updated final_hidden_states with expert contributions added\n    \"\"\"\n    # Clone to avoid modifying input in-place for reference correctness\n    output = final_hidden_states.clone()\n    \n    # Critical atomic accumulation operation\n    # This performs: output[token_indices[i]] += expert_outputs[i]\n    # for all i in parallel with atomic semantics\n    output.index_add_(dim=0, index=token_indices, source=expert_outputs)\n\n    return output\n"
}

